(() => {
  const raw = (v) => String(v === undefined || v === null ? '' : v).trim().toLowerCase();
  const parse = (value) => {
    const v = raw(value);
    if (v === '' || v === 'none') return null;
    if (v.startsWith('#')) {
      const hex = v.length === 4 ? v.slice(1).split('').map((c) => c + c).join('') : v.slice(1);
      if (hex.length < 6) return null;
      return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
    }
    if (v.startsWith('color(srgb')) {
      const body = v.slice(v.indexOf('(') + 1, v.indexOf(')'));
      const parts = body.split(' ').filter((x) => x !== '');
      if (parts.length < 4) return null;
      return [1, 2, 3].map((i) => Math.round(Number(parts[i]) * 255));
    }
    if (v.startsWith('hsl')) {
      const inner = v.slice(v.indexOf('(') + 1, v.indexOf(')'));
      const parts = inner.split(',').map((x) => x.trim());
      if (parts.length < 3) return null;
      const h = Number.parseFloat(parts[0]);
      const s = Number.parseFloat(parts[1]) / 100;
      const l = Number.parseFloat(parts[2]) / 100;
      if ([h, s, l].some((n) => Number.isNaN(n))) return null;
      const c = (1 - Math.abs(2 * l - 1)) * s;
      const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
      const m = l - c / 2;
      let rgb;
      if (h < 60) rgb = [c, x, 0];
      else if (h < 120) rgb = [x, c, 0];
      else if (h < 180) rgb = [0, c, x];
      else if (h < 240) rgb = [0, x, c];
      else if (h < 300) rgb = [x, 0, c];
      else rgb = [c, 0, x];
      return rgb.map((ch) => Math.round((ch + m) * 255));
    }
    if (!v.startsWith('rgb')) return null;
    const inner = v.slice(v.indexOf('(') + 1, v.indexOf(')'));
    return inner.split(',').map((x) => Number.parseFloat(x)).slice(0, 3).map((x) => Math.round(x));
  };
  const lin = (x) => {
    const v = x / 255;
    return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  };
  const lum = (c) => 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]);
  const ratio = (a, b) => {
    if (a === null || b === null) return 0;
    const x = lum(a);
    const y = lum(b);
    return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
  };
  const dist = (a, b) => (a === null || b === null ? 0 : Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]));
  const prop = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  window.__ac = { parse, ratio, dist, prop };

  const THEMES = ['current', 'blue-topaz', 'catppuccin', 'nordic', 'retronotes', 'wasp'];
  const MODES = ['light', 'dark'];
  const MIN_TEXT = 4.5;
  const run = (surface) => {
    const root = document.documentElement;
    const started = { theme: root.dataset.theme, mode: root.dataset.mode };
    const rows = [];
    const failures = [];
    const el = (sel) => document.querySelector(sel);
    const css = (node, name) => (node === null ? '' : getComputedStyle(node)[name]);
    const same = (a, b) => {
      const x = parse(a);
      const y = parse(b);
      return x !== null && y !== null && dist(x, y) === 0;
    };
    for (const theme of THEMES) {
      for (const mode of MODES) {
        root.dataset.theme = theme;
        root.dataset.mode = mode;
        void document.body.offsetHeight;
        const label = theme + '/' + mode;
        const t = {
          bg: prop('--bg'),
          surface: prop('--surface'),
          surface2: prop('--surface-2'),
          text: prop('--text'),
          accent: prop('--accent'),
          accentFg: prop('--accent-fg'),
          ringContrast: prop('--focus-ring-contrast'),
          focusAccent: prop('--focus-accent'),
        };
        const pairs = {
          text_bg: Number(ratio(parse(t.text), parse(t.bg)).toFixed(3)),
          text_surface: Number(ratio(parse(t.text), parse(t.surface)).toFixed(3)),
          text_surface2: Number(ratio(parse(t.text), parse(t.surface2)).toFixed(3)),
          accent_pair: Number(ratio(parse(t.accentFg), parse(t.accent)).toFixed(3)),
          ring_on_surface: Number(ratio(parse(t.ringContrast), parse(t.surface)).toFixed(3)),
          ring_on_surface2: Number(ratio(parse(t.ringContrast), parse(t.surface2)).toFixed(3)),
        };
        const row = { theme, mode, scheme: getComputedStyle(root).colorScheme, tokens: t, pairs, surface: {} };
        if (row.scheme !== mode) failures.push(label + ': color-scheme=' + row.scheme);
        for (const key of Object.keys(pairs)) {
          if (!(pairs[key] >= MIN_TEXT)) failures.push(label + ': ' + key + '=' + pairs[key]);
        }
        if (t.focusAccent === '') failures.push(label + ': нет --focus-accent');
        if (surface === 'map') {
          const canvas = el('.canvas');
          if (canvas === null) {
            failures.push(label + ': нет .canvas');
          } else {
            row.surface = {
              background: css(canvas, 'backgroundColor'),
              image: css(canvas, 'backgroundImage').includes('radial-gradient') ? 'grid' : 'none',
              color: css(canvas, 'color'),
            };
            if (!same(row.surface.background, t.bg)) {
              failures.push(label + ': холст не в цвете --bg (' + row.surface.background + ' ≠ ' + t.bg + ')');
            }
            if (row.surface.image !== 'grid') failures.push(label + ': у холста нет сетки без картинки');
          }
        } else if (surface === 'diary') {
          const screen = el('.chronicle');
          const filter = el('.chron-filter');
          const day = el('.cal-day');
          if (screen === null || filter === null || day === null) {
            failures.push(label + ': нет .chronicle/.chron-filter/.cal-day');
          } else {
            row.surface = {
              background: css(screen, 'backgroundColor'),
              color: css(screen, 'color'),
              filter_items: filter.children.length,
              day_cells: document.querySelectorAll('.cal-day').length,
            };
            if (!same(row.surface.background, t.bg)) {
              failures.push(label + ': полотно дневника не в цвете --bg (' + row.surface.background + ')');
            }
            if (!same(row.surface.color, t.text)) {
              failures.push(label + ': текст дневника не --text (' + row.surface.color + ')');
            }
            if (row.surface.filter_items < 1) failures.push(label + ': отбор пуст');
          }
        } else {
          const dialog = el('.dialog-box');
          if (dialog === null) {
            failures.push(label + ': нет .dialog-box');
          } else {
            row.surface = {
              background: css(dialog, 'backgroundColor'),
              color: css(dialog, 'color'),
            };
            row.surface.contrast = Number(
              ratio(parse(row.surface.color), parse(row.surface.background)).toFixed(3),
            );
            if (!same(row.surface.background, t.surface)) {
              failures.push(label + ': модалка не в цвете --surface (' + row.surface.background + ')');
            }
            if (!(row.surface.contrast >= MIN_TEXT)) {
              failures.push(label + ': текст модалки ' + row.surface.contrast);
            }
          }
        }
        rows.push(row);
      }
    }
    root.dataset.theme = started.theme;
    root.dataset.mode = started.mode;
    window.__mx.lastRows = rows;
    return {
      ok: failures.length === 0,
      surface,
      combos: rows.length,
      themes: THEMES.length,
      modes: MODES.length,
      failures: failures.slice(0, 10),
    };
  };
  window.__mx = { run };
  return true;
})()
